var e=new Set([`IDR`,`JPY`,`KRW`,`VND`]);function t(t,n){if(!Number.isFinite(n))return`${t} 0.00`;let r=(t||`USD`).toUpperCase();if(e.has(r)){let e=n<0,r=Math.abs(Math.round(n)).toString().replace(/\B(?=(\d{3})+(?!\d))/g,`,`);return`${t} ${e?`-`:``}${r}`}let i=n<0,a=Math.abs(Math.round(n)),o=a%100,s=Math.floor(a/100).toString().replace(/\B(?=(\d{3})+(?!\d))/g,`,`);return`${t} ${`${i?`-`:``}${s}.${String(o).padStart(2,`0`)}`}`}export{t};